GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """
    Greedy placement trying several model orderings; each model is assigned to
    the GPU minimizing the KVPR after placement, subject to memory capacity.
    The ordering yielding the lowest max KVPR is returned. Guards against
    zero remaining memory (division by zero) by treating it as infinite KVPR.
    """

    def try_order(order):
        placement = {g: [] for g in range(gpu_num)}
        free = [GPU_MEM_SIZE] * gpu_num
        load = [0.0] * gpu_num
        for model in order:
            r = model.req_rate / model.slo
            best, best_kv = None, float('inf')
            for g in range(gpu_num):
                rem = free[g] - model.model_size
                if rem > 0:
                    kvpr = (load[g] + r) / rem
                elif rem == 0:
                    # Model exactly fills remaining memory; feasible only if no load
                    if load[g] + r <= 0:
                        kvpr = 0.0
                    else:
                        continue
                else:
                    continue
                if kvpr < best_kv:
                    best_kv, best = kvpr, g
            if best is None:
                return None
            placement[best].append(model)
            load[best] += r
            free[best] -= model.model_size
        worst = max((load[g] / free[g]) if free[g] > 0 else
                    (0.0 if load[g] == 0 else float('inf'))
                    for g in range(gpu_num))
        return placement, worst

    # Complementary-pairing constructive heuristic with reserve headroom:
    # models sorted by rate density (r/s) descending; a GPU is forbidden if
    # its post-placement free memory drops below the largest remaining model
    # size while another feasible GPU exists. Near-ties (within 5%) prefer
    # the GPU with the most free memory, preserving headroom for big models.
    def try_reserve(order):
        placement = {g: [] for g in range(gpu_num)}
        free = [float(GPU_MEM_SIZE)] * gpu_num
        load = [0.0] * gpu_num
        for i, model in enumerate(order):
            r = model.req_rate / model.slo
            remaining_max = max((m.model_size for m in order[i + 1:]), default=0.0)
            cands = []
            for g in range(gpu_num):
                rem = free[g] - model.model_size
                if rem <= 0:
                    continue
                if rem < remaining_max and any(
                        free[h] - model.model_size >= remaining_max
                        for h in range(gpu_num) if h != g):
                    continue  # reserve violated, feasible alternative exists
                cands.append(((load[g] + r) / rem, -free[g], g))
            if not cands:
                return None
            cands.sort()
            best_kv = cands[0][0]
            best_g = cands[0][2]
            for kv, negfree, g in cands:
                if kv <= best_kv * 1.05 + 1e-12:
                    best_g = g  # cands sorted by -free: first near-tie has max free
                    break
            placement[best_g].append(model)
            load[best_g] += r
            free[best_g] -= model.model_size
        worst = max((load[g] / free[g]) if free[g] > 0 else
                    (0.0 if load[g] == 0 else float('inf'))
                    for g in range(gpu_num))
        return placement, worst

    orderings = [
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: m.req_rate / m.slo / m.model_size, reverse=True),
        sorted(models, key=lambda m: m.model_size / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size / (m.req_rate / m.slo), reverse=True),
        sorted(models, key=lambda m: m.req_rate / m.slo * m.model_size, reverse=True),
    ]
    best = try_reserve(orderings[0])
    for order in orderings:
        for res in (try_order(order), try_reserve(order)):
            if res is not None and (best is None or res[1] < best[1]):
                best = res
    if best is None:
        raise ValueError("Unable to place all models within GPU memory.")
    placement = best[0]

    # Memetic evolutionary search: population seeded by all feasible greedy
    # placements (try_order / try_reserve over every ordering). Each child is
    # produced by GPU-group crossover (whole GPU model groups sampled from two
    # parents; duplicate models kept on the lower-KVPR GPU; orphans re-inserted
    # by best-fit greedy), optional mutation (random move/swap), then one
    # steepest-descent move/swap local-search pass. Hard caps: population 12,
    # <= 40 generations, ~2000 total child evaluations per instance. The
    # incumbent greedy placement is preserved as a guaranteed fallback.
    import random
    rng = random.Random(12345)

    if len(models) == 0 or gpu_num <= 0:
        return placement
    idx = {id(m): i for i, m in enumerate(models)}
    rate = [m.req_rate / m.slo for m in models]
    size = [m.model_size for m in models]

    def eval_placement(pl):
        vals = []
        for g in range(gpu_num):
            load = sum(rate[idx[id(m)]] for m in pl[g])
            mem = GPU_MEM_SIZE - sum(m.model_size for m in pl[g])
            if mem > 0:
                vals.append(load / mem)
            else:
                vals.append(0.0 if load == 0 else float('inf'))
        vals.sort(reverse=True)
        return vals[0], vals[1] if len(vals) > 1 else 0.0

    def better(a, b):
        return a[0] < b[0] - 1e-12 or (abs(a[0] - b[0]) <= 1e-12 and a[1] < b[1] - 1e-12)

    def best_fit_reinsert(pl, missing):
        for m in missing:
            i = idx[id(m)]
            best, best_kv = None, float('inf')
            for g in range(gpu_num):
                mem = GPU_MEM_SIZE - sum(x.model_size for x in pl[g]) - m.model_size
                if mem > 0:
                    kv = (sum(rate[idx[id(x)]] for x in pl[g]) + rate[i]) / mem
                    if kv < best_kv:
                        best_kv, best = kv, g
            if best is None:
                return False
            pl[best].append(m)
        return True

    # Seed population from all feasible greedy results
    seeds = []
    for order in orderings:
        for res in (try_order(order), try_reserve(order)):
            if res is not None:
                seeds.append({g: list(res[0][g]) for g in range(gpu_num)})
    if placement not in [None]:
        seeds.insert(0, {g: list(placement[g]) for g in range(gpu_num)})
    pop = []
    pop_scores = []
    seen = set()
    for s in seeds:
        key = tuple(tuple(idx[id(m)] for m in s[g]) for g in range(gpu_num))
        if key in seen:
            continue
        seen.add(key)
        sc = eval_placement(s)
        if sc[0] < float('inf'):
            pop.append(s)
            pop_scores.append(sc)

    def mutate(pl):
        q = {g: list(pl[g]) for g in range(gpu_num)}
        occ = [(g, i) for g in range(gpu_num) for i in range(len(q[g]))]
        if not occ:
            return q, True
        if rng.random() < 0.5 and gpu_num > 1:
            g, i = rng.choice(occ)
            h = rng.randrange(gpu_num)
            if h != g:
                m = q[g].pop(i)
                q[h].append(m)
        else:
            if len(occ) >= 2:
                (a, ia), (b, ib) = rng.sample(occ, 2)
                q[a][ia], q[b][ib] = q[b][ib], q[a][ia]
        ok = all(GPU_MEM_SIZE - sum(x.model_size for x in q[g]) > 0 or not q[g]
                 for g in range(gpu_num))
        return q, ok

    def local_pass(pl):
        # Steepest descent over single moves and pairwise swaps, one pass.
        cur = eval_placement(pl)
        while True:
            best_key, best_move = cur, None
            for a in range(gpu_num):
                for ia in range(len(pl[a]) - 1, -1, -1):
                    m = pl[a][ia]
                    for b in range(gpu_num):
                        if b == a:
                            continue
                        mem = GPU_MEM_SIZE - sum(x.model_size for x in pl[b])
                        if mem - m.model_size <= 0:
                            continue
                        pl[a].pop(ia)
                        pl[b].append(m)
                        k = eval_placement(pl)
                        pl[b].pop()
                        pl[a].insert(ia, m)
                        if better(k, best_key):
                            best_key, best_move = k, ('m', a, ia, b)
                for ia in range(len(pl[a])):
                    ma = pl[a][ia]
                    for b in range(a + 1, gpu_num):
                        for ib in range(len(pl[b])):
                            mb = pl[b][ib]
                            mem_a = GPU_MEM_SIZE - sum(x.model_size for x in pl[a])
                            mem_b = GPU_MEM_SIZE - sum(x.model_size for x in pl[b])
                            if mem_a + ma.model_size - mb.model_size <= 0:
                                continue
                            if mem_b + mb.model_size - ma.model_size <= 0:
                                continue
                            pl[a][ia], pl[b][ib] = mb, ma
                            k = eval_placement(pl)
                            pl[a][ia], pl[b][ib] = ma, mb
                            if better(k, best_key):
                                best_key, best_move = k, ('s', a, ia, b, ib)
            if best_move is None:
                break
            if best_move[0] == 'm':
                _, a, ia, b = best_move
                m = pl[a].pop(ia)
                pl[b].append(m)
            else:
                _, a, ia, b, ib = best_move
                pl[a][ia], pl[b][ib] = pl[b][ib], pl[a][ia]
            cur = best_key
        return cur

    evals = 0
    for gen in range(40):
        if evals >= 2000 or len(pop) < 2:
            break
        new_pop, new_scores = [], []
        # Elitism: keep best quarter
        order_i = sorted(range(len(pop)), key=lambda i: pop_scores[i])
        for i in order_i[:max(1, len(pop) // 4)]:
            new_pop.append(pop[i])
            new_scores.append(pop_scores[i])
        while len(new_pop) < 12 and evals < 2000:
            cand = rng.sample(range(len(pop)), 2)
            p1 = pop[cand[0]] if pop_scores[cand[0]] <= pop_scores[cand[1]] else pop[cand[1]]
            cand2 = rng.sample(range(len(pop)), 2)
            p2 = pop[cand2[0]] if pop_scores[cand2[0]] <= pop_scores[cand2[1]] else pop[cand2[1]]
            # Group crossover: each child GPU inherits a whole group from p1 or p2
            child = {}
            for g in range(gpu_num):
                child[g] = list((p1 if rng.random() < 0.5 else p2)[g])
            # Resolve duplicates: keep copy whose GPU has lower current KVPR
            placed = {}
            for g in range(gpu_num):
                keep = []
                for m in child[g]:
                    i = idx[id(m)]
                    if i in placed:
                        pg = placed[i]
                        mem_pg = GPU_MEM_SIZE - sum(x.model_size for x in child[pg])
                        mem_g = GPU_MEM_SIZE - sum(x.model_size for x in child[g]) - m.model_size
                        kv_pg = (sum(rate[idx[id(x)]] for x in child[pg]) / mem_pg
                                 if mem_pg > 0 else float('inf'))
                        kv_g = ((sum(rate[idx[id(x)]] for x in child[g]) + rate[i]) / mem_g
                                if mem_g > 0 else float('inf'))
                        if kv_g < kv_pg:
                            child[pg].remove(m)
                            placed[i] = g
                            keep.append(m)
                    else:
                        placed[i] = g
                        keep.append(m)
                child[g] = keep
            missing = [m for m in models if idx[id(m)] not in placed]
            ok = best_fit_reinsert(child, missing)
            evals += 1
            if not ok:
                continue
            if rng.random() < 0.3:
                child, ok = mutate(child)
                evals += 1
                if not ok:
                    continue
            sc = local_pass(child)
            evals += 1
            new_pop.append(child)
            new_scores.append(sc)
        pop, pop_scores = new_pop, new_scores

    best_i = min(range(len(pop)), key=lambda i: pop_scores[i])
    if better(pop_scores[best_i], eval_placement(placement)):
        placement = pop[best_i]
    return placement

